import{_ as d,o as p,c as e,a2 as i}from"./chunks/framework.BZO4qERu.js";const x=JSON.parse('{"title":"MIME Type (MIME 类型)","description":"","frontmatter":{},"headers":[],"relativePath":"mimeTypeGlossary.md","filePath":"mimeTypeGlossary.md","lastUpdated":1679401943000}'),a={name:"mimeTypeGlossary.md"};function r(o,t,n,m,s,h){return p(),e("div",null,[...t[0]||(t[0]=[i('<h1 id="mime-type-mime-类型" tabindex="-1">MIME Type (MIME 类型)</h1><p>媒体类型, 也称为 MIME 类型 (Multipurpose Internet Mail Extensions), 是一种标准, 用来表示 [ 文档 / 文件 / 字节流 ] 的性质和格式.</p><p>通用结构为 <code>type/subtype</code>.</p><p>MIME 的组成结构由类型与子类型两个字符串及 &#39;/&#39; 组成, 无空格.</p><p>MIME 类型对大小写不敏感, 传统写法为全部小写.</p><table tabindex="0"><thead><tr><th>类型</th><th>子类型</th><th>MIME</th></tr></thead><tbody><tr><td>text</td><td>plain</td><td>text/plain</td></tr><tr><td></td><td>html</td><td>text/html</td></tr><tr><td></td><td>css</td><td>text/css</td></tr><tr><td></td><td>javascript</td><td>text/javascript</td></tr><tr><td>image</td><td>gif</td><td>image/gif</td></tr><tr><td></td><td>png</td><td>image/png</td></tr><tr><td></td><td>jpeg</td><td>image/jpeg</td></tr><tr><td></td><td>webp</td><td>image/webp</td></tr><tr><td></td><td>svg+xml</td><td>image/svg+xml</td></tr><tr><td></td><td>bmp</td><td>image/bmp</td></tr><tr><td></td><td>x-icon</td><td>image/x-icon</td></tr><tr><td></td><td>vnd.microsoft.icon</td><td>image/vnd.microsoft.icon</td></tr><tr><td>audio</td><td>wav</td><td>audio/wav</td></tr><tr><td></td><td>wave</td><td>audio/wave</td></tr><tr><td></td><td>x-wav</td><td>audio/x-wav</td></tr><tr><td></td><td>x-pn-wav</td><td>audio/x-pn-wav</td></tr><tr><td></td><td>midi</td><td>audio/midi</td></tr><tr><td></td><td>mpeg</td><td>audio/mpeg</td></tr><tr><td></td><td>webm</td><td>audio/webm</td></tr><tr><td></td><td>ogg</td><td>audio/ogg</td></tr><tr><td>video</td><td>webm</td><td>video/webm</td></tr><tr><td></td><td>ogg</td><td>video/ogg</td></tr><tr><td>application</td><td>octet-stream</td><td>application/octet-stream</td></tr><tr><td></td><td>pkcs12</td><td>application/pkcs12</td></tr><tr><td></td><td>vnd.mspowerpoint</td><td>application/vnd.mspowerpoint</td></tr><tr><td></td><td>xhtml+xml</td><td>application/xhtml+xml</td></tr><tr><td></td><td>xml+html</td><td>application/xml+html</td></tr><tr><td></td><td>xml</td><td>application/xml</td></tr><tr><td></td><td>pdf</td><td>application/pdf</td></tr><tr><td></td><td>ogg</td><td>application/ogg</td></tr><tr><td></td><td>json</td><td>application/json</td></tr><tr><td></td><td>x-rar-compressed</td><td>application/x-rar-compressed</td></tr><tr><td>multipart</td><td>form-data</td><td>multipart/form-data</td></tr><tr><td></td><td>byteranges</td><td>multipart/byteranges</td></tr></tbody></table><blockquote><p>参阅: <a href="https://developer.mozilla.org/zh-CN/docs/Web/HTTP/Basics_of_HTTP/MIME_types" target="_blank" rel="noreferrer">MDN</a></p></blockquote><hr><h2 id="text" tabindex="-1">text</h2><p>普通文本文件.</p><h3 id="plain" tabindex="-1">plain</h3><p>文本文件默认值.</p><p><code>text/plain</code> 可代表未知的文本文件.</p><h3 id="html" tabindex="-1">html</h3><p>HTML 类型.</p><h3 id="css" tabindex="-1">css</h3><p>CSS 类型.</p><p>网页中要被解析为 CSS 的任何文件必须指定 MIME 为 <code>text/css</code>.</p><p>通常, 服务器不识别 <code>*.css</code> 文件的 MIME 类型, 必须为其指定明确的 MIME 类型.</p><h3 id="javascript" tabindex="-1">javascript</h3><p>JavaScript 类型.</p><p>据 HTML 标准, 应该总是使用 MIME 类型 <code>text/javascript</code> 表示 JavaScript 文件.</p><h2 id="image" tabindex="-1">image</h2><p>图像文件.</p><h3 id="gif" tabindex="-1">gif</h3><p>GIF 图像 (无损耗压缩方面被 PNG 所替代).</p><p>该图像类型是 Web 安全的, 可随时在 Web 页面中使用.</p><h3 id="png" tabindex="-1">png</h3><p>PNG 图像.</p><p>该图像类型是 Web 安全的, 可随时在 Web 页面中使用.</p><h3 id="jpeg" tabindex="-1">jpeg</h3><p>JPEG 图像.</p><p>该图像类型是 Web 安全的, 可随时在 Web 页面中使用.</p><h3 id="webp" tabindex="-1">webp</h3><p>WebP 图像.</p><p>该图像类型 <strong>并非</strong> Web 安全的.</p><p>因每个新增图像类型都会增加代码量, 并带来一些安全问题, 浏览器供应商对此会额外谨慎.</p><h3 id="svg-xml" tabindex="-1">svg+xml</h3><p>SVG 图像 (矢量图).</p><h3 id="bmp" tabindex="-1">bmp</h3><p>JPEG 图像.</p><h3 id="x-icon" tabindex="-1">x-icon</h3><p>ICO 图像.</p><p>很多浏览器已支持 <code>image/x-icon</code> MIME 类型.</p><h3 id="vnd-microsoft-icon" tabindex="-1">vnd.microsoft.icon</h3><p>微软 ICO 图像.</p><p>尽管 <code>image/vnd.microsoft.icon</code> 在 ANA 已注册, 它仍为得到广泛支持.</p><p>可使用 <code>image/x-icon</code> 作为替代品.</p><blockquote><p>参阅: <a href="https://www.iana.org/assignments/media-types/image/vnd.microsoft.icon" target="_blank" rel="noreferrer">https://www.iana.org/assignments/media-types/image/vnd.microsoft.icon</a></p></blockquote><h2 id="audio" tabindex="-1">audio</h2><p>音频文件.</p><h3 id="wav" tabindex="-1">wav</h3><p>音频流媒体文件类型, 一般支持 PCM 音频编码.</p><h3 id="wave" tabindex="-1">wave</h3><p>音频流媒体文件类型, 一般支持 PCM 音频编码.</p><h3 id="x-wav" tabindex="-1">x-wav</h3><p>音频流媒体文件类型, 一般支持 PCM 音频编码.</p><h3 id="x-pn-wav" tabindex="-1">x-pn-wav</h3><p>音频流媒体文件类型, 一般支持 PCM 音频编码.</p><h3 id="midi" tabindex="-1">midi</h3><p>MIDI 类型.</p><h3 id="mpeg" tabindex="-1">mpeg</h3><p>MPEG 类型.</p><h3 id="webm" tabindex="-1">webm</h3><p>WebM 音频文件类型.</p><p>Vorbis 和 Opus 是其最常用的解码器.</p><h3 id="ogg" tabindex="-1">ogg</h3><p>采用 OGG 多媒体文件格式的音频文件.</p><p>Vorbis 是其最常用的音频解码器.</p><h2 id="video" tabindex="-1">video</h2><p>视频文件.</p><h3 id="webm-1" tabindex="-1">webm</h3><p>采用 WebM 视频文件格式的音视频文件.</p><p>VP8 和 VP9 是其最常用的视频解码器, Vorbis 和 Opus 是其最常用的音频解码器.</p><h3 id="ogg-1" tabindex="-1">ogg</h3><p>采用 OGG 多媒体文件格式的音视频文件.</p><p>常用的视频解码器是 Theora, 音频解码器为 Vorbis.</p><h2 id="application" tabindex="-1">application</h2><p>二进制数据类型.</p><h3 id="octet-stream" tabindex="-1">octet-stream</h3><p>这是应用程序文件的默认值, 代表未知的应用程序文件.</p><h3 id="pkcs12" tabindex="-1">pkcs12</h3><p>PKCS#12 类型.</p><p>在密码学中, PKCS#12 定义了一种存档文件格式, 用于将许多密码学对象作为一个文件来存储.</p><p>它通常用于捆绑私钥及其 X.509 证书, 或捆绑信任链的所有成员.</p><h3 id="vnd-mspowerpoint" tabindex="-1">vnd.mspowerpoint</h3><p>微软 PowerPoint 类型.</p><h3 id="xhtml-xml" tabindex="-1">xhtml+xml</h3><p>XHTML 类型.</p><h3 id="xml-html" tabindex="-1">xml+html</h3><p>XHTML 的 MIME 类型之一.</p><p>因 HTML5 统一了这些格式, 现已较少使用, 建议使用 <code>text/html</code></p><h3 id="xml" tabindex="-1">xml</h3><p>XML 类型.</p><h3 id="pdf" tabindex="-1">pdf</h3><p>PDF 类型.</p><h3 id="ogg-2" tabindex="-1">ogg</h3><p>采用 OGG 多媒体文件格式的音视频文件类型.</p><p>常用的视频解码器是 Theora, 音频解码器为 Vorbis.</p><h3 id="json" tabindex="-1">json</h3><p>JSON 类型.</p><blockquote><p>参阅: <a href="https://www.iana.org/assignments/media-types/application/json" target="_blank" rel="noreferrer">https://www.iana.org/assignments/media-types/application/json</a></p></blockquote><h3 id="x-rar-compressed" tabindex="-1">x-rar-compressed</h3><p>RAR 编码文件.</p><h2 id="multipart" tabindex="-1">multipart</h2><p>Multipart 类型表示细分领域的文件类型的种类, 经常对应不同的 MIME 类型, 是复合文件的一种表现方式.</p><h3 id="form-data" tabindex="-1">form-data</h3><p><code>multipart/form-data</code> 可用于 HTML 表单从浏览器发送信息给服务器.</p><h3 id="byteranges" tabindex="-1">byteranges</h3><p><code>multipart/byteranges</code> 用于把部分响应报文发送回浏览器.</p>',110)])])}const b=d(a,[["render",r]]);export{x as __pageData,b as default};
